package br.com.onda;
import android.content.*;
import android.media.*;
import android.net.Uri;
import androidx.media3.common.*;
import androidx.media3.session.*;
import com.google.common.util.concurrent.ListenableFuture;
import java.io.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class EvolutionTest {
 File fixture(String name)throws Exception{File f=File.createTempFile("evolution-",".bin",getInstrumentation().getTargetContext().getCacheDir());try(InputStream in=getInstrumentation().getContext().getAssets().open(name);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return f;}
 @Test public void localVideoConvertsToMp3AndM4aWithoutChangingOriginal()throws Exception{File source=fixture("combined.mp4"),out=File.createTempFile("evolution-",".out",source.getParentFile());byte[] original=java.nio.file.Files.readAllBytes(source.toPath());try{for(String format:new String[]{"mp3","m4a"}){LocalAudio.convert(source,out,format,()->{});MediaExtractor ex=new MediaExtractor();try{ex.setDataSource(out.getPath());assertEquals(1,ex.getTrackCount());assertEquals(format.equals("mp3")?"audio/mpeg":"audio/mp4a-latm",ex.getTrackFormat(0).getString(MediaFormat.KEY_MIME));assertTrue(ex.getTrackFormat(0).getLong(MediaFormat.KEY_DURATION)>1000000);}finally{ex.release();}assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));}}finally{source.delete();out.delete();}}
 @Test public void rejectsNonAacAndChecksCancellation()throws Exception{File source=fixture("speech.wav"),out=File.createTempFile("evolution-",".out",source.getParentFile());try{try{LocalAudio.convert(source,out,"mp3",()->{});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("AAC"));}File aac=fixture("audio.m4a");try{try{LocalAudio.convert(aac,out,"m4a",()->{throw new InterruptedIOException("Cancelado");});fail();}catch(InterruptedIOException expected){}}finally{aac.delete();}}finally{source.delete();out.delete();}}
 @Test public void conversionServiceRegistersCompletedOutput()throws Exception{Context c=getInstrumentation().getTargetContext();String old=c.getSharedPreferences(DownloadHistory.PREF,0).getString("data",null);File source=fixture("combined.mp4"),out=File.createTempFile("evolution-",".m4a",c.getCacheDir());Intent job=new Intent(c,MediaDownloadService.class).putExtra("conversion_source",Uri.fromFile(source).toString()).putExtra("destination",Uri.fromFile(out).toString()).putExtra("format","m4a").putExtra("title","Conversão nativa");try{c.getSharedPreferences("downloads",0).edit().putString("status","").commit();getInstrumentation().runOnMainSync(()->c.startForegroundService(job));long end=System.currentTimeMillis()+60000;String status="";while(System.currentTimeMillis()<end){status=c.getSharedPreferences("downloads",0).getString("status","");if(!MediaDownloadService.activeDownload&&(status.startsWith("Conversão concluída")||status.startsWith("Operação interrompida")))break;Thread.sleep(100);}assertTrue(status,status.startsWith("Conversão concluída"));assertTrue(DownloadHistory.read(c).stream().anyMatch(e->e.uri.equals(Uri.fromFile(out).toString())&&e.state.equals("done")));assertTrue(source.length()>0);}finally{c.stopService(job);source.delete();out.delete();SharedPreferences.Editor e=c.getSharedPreferences(DownloadHistory.PREF,0).edit();if(old==null)e.remove("data");else e.putString("data",old);e.commit();}}
 @Test public void fileSortKeepsFoldersFirstAndUnknownSizesLast(){List<OndaFiles.Item> entries=new ArrayList<>(Arrays.asList(new OndaFiles.Item(Uri.parse("content://test/1"),"Áudio","audio/mpeg",10,1),new OndaFiles.Item(Uri.parse("content://test/2"),"Pasta",android.provider.DocumentsContract.Document.MIME_TYPE_DIR,0,2),new OndaFiles.Item(Uri.parse("content://test/3"),"Grande","audio/mpeg",100,3),new OndaFiles.Item(Uri.parse("content://test/4"),"Sem tamanho","audio/mpeg",-1,0)));entries.sort(OndaFiles.order(2));assertTrue(entries.get(0).folder);assertEquals("Grande",entries.get(1).name);assertEquals("Sem tamanho",entries.get(3).name);}
 @Test public void audioSpeedAndSeekKeepActualPlayerPaused()throws Exception{android.app.Instrumentation ins=getInstrumentation();Context c=ins.getTargetContext();int old=AudioPlaybackOptions.saved(c);File source=fixture("speech.wav");ListenableFuture<MediaController>[] connection=new ListenableFuture[1];ins.runOnMainSync(()->connection[0]=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());MediaController player=connection[0].get(15,TimeUnit.SECONDS);try{ins.runOnMainSync(()->{player.pause();player.setMediaItem(MediaItem.fromUri(Uri.fromFile(source)));player.prepare();});long end=System.currentTimeMillis()+10000;boolean[] ready={false};while(System.currentTimeMillis()<end){ins.runOnMainSync(()->ready[0]=player.getPlaybackState()==Player.STATE_READY);if(ready[0])break;Thread.sleep(100);}assertTrue(ready[0]);ins.runOnMainSync(()->AudioPlaybackOptions.apply(c,player,3));Thread.sleep(300);ins.runOnMainSync(()->{assertEquals(1.25f,player.getPlaybackParameters().speed,.001f);assertEquals(1f,player.getPlaybackParameters().pitch,.001f);assertFalse(player.getPlayWhenReady());AudioPlaybackOptions.seek(player,30000);});Thread.sleep(300);ins.runOnMainSync(()->{assertTrue(player.getCurrentPosition()>10000);assertFalse(player.getPlayWhenReady());AudioPlaybackOptions.seek(player,-10000);});Thread.sleep(300);ins.runOnMainSync(()->assertTrue(player.getCurrentPosition()<10000));}finally{ins.runOnMainSync(()->{player.pause();player.clearMediaItems();AudioPlaybackOptions.apply(c,player,old);MediaController.releaseFuture(connection[0]);});c.getSharedPreferences("playback_tools",0).edit().putInt("speed",old).commit();source.delete();}}
}
